        begin=end+1; end=begin+sizes[oid]
        raw=batch[begin:end]
        if batch[end:end+1]!=b"\n" or hashlib.sha1(b"blob "+str(len(raw)).encode()+b"\0"+raw).hexdigest()!=oid:raise ValueError("blob content address differs")
        raw_by_oid[oid]=raw
